const ISSUER_SEED = "<TESTNET_SEED_REDACTED>";

async function main(): Promise<void> {
  const client = await connectTestnetClient();
  try {
    const issuerWallet = Wallet.fromSeed(ISSUER_SEED);
    const issuer = new MptIssuer(client, issuerWallet);

    const x = Wallet.generate();
    for (const w of [x]) {
      await submitAndVerify(client, issuerWallet, {
        TransactionType: "Payment",
        Account: issuerWallet.address,
        Destination: w.address,
        Amount: (5_000_000).toString(),
      });
    }
    console.log("X:", x.address);

    const { issuanceId } = await issuer.createIssuance({
      assetScale: 0,
      maximumAmount: "1000000",
    });
    console.log("Issuance:", issuanceId);

    await submitAndVerify(client, x, {
      TransactionType: "MPTokenAuthorize",
      Account: x.address,
      MPTokenIssuanceID: issuanceId,
    });
    await issuer.approveHolder(issuanceId, x.address);
    await issuer.sendTokens(issuanceId, x.address, "100");
    console.log("Sent 100 to X");

    await issuer.globalFreeze(issuanceId);
    console.log("Globally froze issuance");

    try {
      await issuer.sendTokens(issuanceId, x.address, "1");
      console.log("issuer -> X during GLOBAL freeze: SUCCEEDED (unexpected)");
    } catch (error) {
      if (error instanceof TransactionFailedError) {
        console.log(`issuer -> X during GLOBAL freeze: FAILED as expected (${error.resultCode})`);
      } else {
        throw error;
      }
    }

    try {
      await submitAndVerify(client, x, {
        TransactionType: "Payment",
        Account: x.address,
        Destination: issuerWallet.address,
        Amount: { mpt_issuance_id: issuanceId, value: "1" },
