      if (error instanceof TransactionFailedError) {
        console.log(`X -> issuer during GLOBAL freeze: FAILED (${error.resultCode})`);
      } else {
        throw error;
      }
    }

    await issuer.globalUnfreeze(issuanceId);
    console.log("Unfroze globally");
  } finally {
    await client.disconnect();
  }
}

main().catch((e) => {
  console.error(e);
  process.exitCode = 1;
});

