import type { Client, MPTokenMetadata, TxResponse, Wallet } from "xrpl";
import {
  encodeMPTokenMetadata,
  MPTokenAuthorizeFlags,
  MPTokenIssuanceCreateFlags,
  MPTokenIssuanceSetFlags,
  parseMPTokenIssuanceFlags,
} from "xrpl";

import { submitAndVerify } from "./txSubmit";
import { hasFlag, MPTokenFlags } from "./mptFlags";

export interface CreateIssuanceParams {
  /** Number of decimal places used when displaying amounts (0-19). The
   * ledger itself always stores/transfers raw integers; see `src/amounts.ts`. */
  assetScale: number;
  /** Maximum total supply, in raw base units (a string integer). */
  maximumAmount: string;
  /** Transfer fee in basis points of a unit's value (0-50000, i.e. 0-50%). */
  transferFee?: number;
  /** Structured token metadata (XLS-89), hex-encoded onto the wire via the
   * SDK's `encodeMPTokenMetadata`. */
  metadata?: MPTokenMetadata;
  /** Whether holders may transfer to each other (not just to/from the issuer).
   * Defaults to true. */
  allowHolderToHolderTransfer?: boolean;
}

export interface IssuanceState {
  issuanceId: string;
  issuer: string;
  outstandingAmount: string;
  maximumAmount?: string;
  assetScale?: number;
  transferFee?: number;
  globallyLocked: boolean;
  requireAuth: boolean;
  canClawback: boolean;
  canLock: boolean;
}

export interface HolderState {
  issuanceId: string;
  holder: string;
  balance: string;
  authorized: boolean;
  locked: boolean;
}

/**
 * Issuer-side control plane for a single regulated MPT issuance.
 *
 * Every mutating method submits exactly one XRPL transaction (except
 * `banHolder`, which is a clawback-then-revoke compound operation), waits
 * for ledger validation, and throws `TransactionFailedError` on any
 * non-`tesSUCCESS` result. Callers should treat a resolved promise as proof
 * the effect is durably recorded on the ledger.
 */
export class MptIssuer {
  constructor(
    private readonly client: Client,
    private readonly issuerWallet: Wallet,
  ) {}

  get issuerAddress(): string {
    return this.issuerWallet.address;
  }

  /**
   * Creates the MPT issuance with the full compliance control surface
   * enabled: authorization-gated holding (allowlist), per-holder and
   * global freeze (lock), and clawback. Returns the new issuance ID.
   */
  async createIssuance(params: CreateIssuanceParams): Promise<{ issuanceId: string; hash: string }> {
    let flags =
      MPTokenIssuanceCreateFlags.tfMPTRequireAuth |
      MPTokenIssuanceCreateFlags.tfMPTCanLock |
      MPTokenIssuanceCreateFlags.tfMPTCanClawback;
    if (params.allowHolderToHolderTransfer ?? true) {
      flags |= MPTokenIssuanceCreateFlags.tfMPTCanTransfer;
    }

    const response = await submitAndVerify(this.client, this.issuerWallet, {
      TransactionType: "MPTokenIssuanceCreate",
      Account: this.issuerAddress,
      AssetScale: params.assetScale,
      MaximumAmount: params.maximumAmount,
      ...(params.transferFee !== undefined ? { TransferFee: params.transferFee } : {}),
      ...(params.metadata !== undefined
        ? { MPTokenMetadata: Buffer.from(params.metadata, "utf8").toString("hex").toUpperCase() }
        : {}),
      Flags: flags,
    });

    const issuanceId = response.result.meta && typeof response.result.meta === "object"
      ? (response.result.meta as { mpt_issuance_id?: string }).mpt_issuance_id
      : undefined;
    if (!issuanceId) {
      throw new Error("MPTokenIssuanceCreate succeeded but no mpt_issuance_id was returned");
    }

    return { issuanceId, hash: response.result.hash };
  }

  /**
   * Allowlist: approves a holder who has already opted in (submitted their
   * own `MPTokenAuthorize`). Required before that holder can receive or
   * send the token, since the issuance is created with `tfMPTRequireAuth`.
   */
  async approveHolder(issuanceId: string, holderAddress: string): Promise<TxResponse> {
    return submitAndVerify(this.client, this.issuerWallet, {
      TransactionType: "MPTokenAuthorize",
      Account: this.issuerAddress,
      MPTokenIssuanceID: issuanceId,
      Holder: holderAddress,
    });
  }

  /** Sends `value` (in display units) of the token from the issuer to a holder. */
  async sendTokens(issuanceId: string, holderAddress: string, value: string): Promise<TxResponse> {
    return submitAndVerify(this.client, this.issuerWallet, {
      TransactionType: "Payment",
      Account: this.issuerAddress,
      Destination: holderAddress,
      Amount: { mpt_issuance_id: issuanceId, value },
    });
  }

  /** Claws back `value` (in display units) of the token from a holder, back to the issuer. */
  async clawback(issuanceId: string, holderAddress: string, value: string): Promise<TxResponse> {
    return submitAndVerify(this.client, this.issuerWallet, {
      TransactionType: "Clawback",
      Account: this.issuerAddress,
      Holder: holderAddress,
      Amount: { mpt_issuance_id: issuanceId, value },
    });
  }

  /**
   * Per-holder freeze: blocks this holder from sending or receiving the
   * token to or from any other holder. The issuer itself remains an exempt
   * counterparty (as with classic trust-line freezes) so that `clawback`
   * and issuer-initiated payments keep working on a frozen account.
   */
  async freezeHolder(issuanceId: string, holderAddress: string): Promise<TxResponse> {
    return submitAndVerify(this.client, this.issuerWallet, {
      TransactionType: "MPTokenIssuanceSet",
      Account: this.issuerAddress,
      MPTokenIssuanceID: issuanceId,
      Holder: holderAddress,
      Flags: MPTokenIssuanceSetFlags.tfMPTLock,
    });
  }

  /** Lifts a per-holder freeze. */
  async unfreezeHolder(issuanceId: string, holderAddress: string): Promise<TxResponse> {
    return submitAndVerify(this.client, this.issuerWallet, {
      TransactionType: "MPTokenIssuanceSet",
      Account: this.issuerAddress,
      MPTokenIssuanceID: issuanceId,
      Holder: holderAddress,
      Flags: MPTokenIssuanceSetFlags.tfMPTUnlock,
    });
  }

  /**
   * Global freeze: blocks movement of the token between any two holders,
   * for the whole issuance at once (e.g. during an incident). As with
   * `freezeHolder`, the issuer remains an exempt counterparty, so this does
   * not prevent the issuer from still running `clawback` or administrative
   * payments while the freeze is in effect.
   */
  async globalFreeze(issuanceId: string): Promise<TxResponse> {
    return submitAndVerify(this.client, this.issuerWallet, {
      TransactionType: "MPTokenIssuanceSet",
      Account: this.issuerAddress,
      MPTokenIssuanceID: issuanceId,
      Flags: MPTokenIssuanceSetFlags.tfMPTLock,
    });
  }

  /** Lifts a global freeze. */
  async globalUnfreeze(issuanceId: string): Promise<TxResponse> {
    return submitAndVerify(this.client, this.issuerWallet, {
      TransactionType: "MPTokenIssuanceSet",
      Account: this.issuerAddress,
      MPTokenIssuanceID: issuanceId,
      Flags: MPTokenIssuanceSetFlags.tfMPTUnlock,
    });
  }

  /**
   * Bans a holder: claws back their entire balance (if any) so they end up
   * holding none of the token, then revokes their authorization so they
   * cannot be paid again while the issuance requires authorization. This is
   * NOT the same as a freeze — authorization revocation is not reversible
   * via `unfreezeHolder`; a banned holder would need to be re-approved via
   * `approveHolder` to ever hold the token again.
   */
  async banHolder(issuanceId: string, holderAddress: string): Promise<TxResponse[]> {
    const results: TxResponse[] = [];

    const holderState = await this.getHolder(issuanceId, holderAddress);
    if (holderState && BigInt(holderState.balance) > 0n) {
      results.push(await this.clawback(issuanceId, holderAddress, holderState.balance));
    }

    results.push(
      await submitAndVerify(this.client, this.issuerWallet, {
        TransactionType: "MPTokenAuthorize",
        Account: this.issuerAddress,
        MPTokenIssuanceID: issuanceId,
        Holder: holderAddress,
        Flags: MPTokenAuthorizeFlags.tfMPTUnauthorize,
      }),
    );

    return results;
  }

  /** Reads the issuance's current supply and compliance-flag state. */
  async getIssuance(issuanceId: string): Promise<IssuanceState> {
    const response = await this.client.request({
      command: "ledger_entry",
      mpt_issuance: issuanceId,
      ledger_index: "validated",
    });
    const node = response.result.node;
    if (node.LedgerEntryType !== "MPTokenIssuance") {
      throw new Error(`Expected an MPTokenIssuance ledger entry, got ${node.LedgerEntryType}`);
    }
    const flags = parseMPTokenIssuanceFlags(node.Flags);

    return {
      issuanceId,
      issuer: node.Issuer,
      outstandingAmount: node.OutstandingAmount,
      maximumAmount: node.MaximumAmount,
      assetScale: node.AssetScale,
      transferFee: node.TransferFee,
      globallyLocked: flags.lsfMPTLocked ?? false,
      requireAuth: flags.lsfMPTRequireAuth ?? false,
      canClawback: flags.lsfMPTCanClawback ?? false,
      canLock: flags.lsfMPTCanLock ?? false,
    };
  }

  /** Reads a holder's balance, authorization, and freeze state. Returns
   * `null` if the holder has never opted in (no MPToken object exists). */
  async getHolder(issuanceId: string, holderAddress: string): Promise<HolderState | null> {
    try {
      const response = await this.client.request({
        command: "ledger_entry",
        mptoken: { mpt_issuance_id: issuanceId, account: holderAddress },
        ledger_index: "validated",
      });
      // The xrpl.js `LedgerEntry` union type omits `MPToken` (a gap in the
      // SDK's type definitions as of v5.3.0), so we narrow through
      // `unknown` and verify the discriminant at runtime instead.
      const node = response.result.node as unknown as {
        LedgerEntryType: string;
        MPTAmount: string;
        Flags: number;
      };
      if (node.LedgerEntryType !== "MPToken") {
        throw new Error(`Expected an MPToken ledger entry, got ${node.LedgerEntryType}`);
      }

      return {
        issuanceId,
        holder: holderAddress,
        balance: node.MPTAmount ?? "0",
        authorized: hasFlag(node.Flags, MPTokenFlags.lsfMPTAuthorized),
        locked: hasFlag(node.Flags, MPTokenFlags.lsfMPTLocked),
      };
    } catch (error) {
      if (error instanceof Error && "data" in error) {
        const data = (error as Error & { data?: { error?: string } }).data;
        if (data?.error === "entryNotFound") {
          return null;
        }
      }
      throw error;
    }
  }
}

import * as fs from "node:fs";
import * as path from "node:path";
import { Wallet, type Client } from "xrpl";

import {
  MptIssuer,
  connectTestnetClient,
  toBaseUnits,
  submitAndVerify,
  TransactionFailedError,
} from "../src";

const ISSUER_SEED = "<TESTNET_SEED_REDACTED>";
// AssetScale is a display-only convention (the ledger always stores/moves
// raw integers); use 0 so the raw amounts on the ledger equal the
// human-readable amounts used throughout this demo.
const ASSET_SCALE = 0;
const HOLDER_STARTING_XRP = "5";

function log(message: string): void {
  console.log(message);
}

async function expectFailure(label: string, fn: () => Promise<unknown>): Promise<void> {
  try {
    await fn();
  } catch (error) {
    if (error instanceof TransactionFailedError) {
      log(`  [OK] ${label} correctly rejected (${error.resultCode})`);
      return;
    }
    throw error;
  }
  throw new Error(`Expected "${label}" to fail, but it succeeded`);
}

async function fundFromIssuer(
  client: Client,
  issuerWallet: Wallet,
  destination: string,
  amountXrp: string,
): Promise<void> {
  await submitAndVerify(client, issuerWallet, {
    TransactionType: "Payment",
    Account: issuerWallet.address,
    Destination: destination,
    Amount: (Number(amountXrp) * 1_000_000).toString(),
  });
}

async function holderOptIn(client: Client, holderWallet: Wallet, issuanceId: string): Promise<void> {
  await submitAndVerify(client, holderWallet, {
    TransactionType: "MPTokenAuthorize",
    Account: holderWallet.address,
    MPTokenIssuanceID: issuanceId,
  });
}

async function holderPayment(
  client: Client,
  fromWallet: Wallet,
  toAddress: string,
  issuanceId: string,
  value: string,
): Promise<void> {
  await submitAndVerify(client, fromWallet, {
    TransactionType: "Payment",
    Account: fromWallet.address,
    Destination: toAddress,
    Amount: { mpt_issuance_id: issuanceId, value },
  });
}

async function main(): Promise<void> {
  const client = await connectTestnetClient();

  try {
    const issuerWallet = Wallet.fromSeed(ISSUER_SEED);
    const issuer = new MptIssuer(client, issuerWallet);
    log(`Issuer: ${issuerWallet.address}`);

    const walletA = Wallet.generate();
    const walletB = Wallet.generate();
    const walletC = Wallet.generate();
    log(`Holder A: ${walletA.address}`);
    log(`Holder B: ${walletB.address}`);
    log(`Holder C: ${walletC.address}`);

    log("\n== Funding holder accounts from issuer ==");
    for (const wallet of [walletA, walletB, walletC]) {
      await fundFromIssuer(client, issuerWallet, wallet.address, HOLDER_STARTING_XRP);
      log(`  Funded ${wallet.address} with ${HOLDER_STARTING_XRP} XRP`);
    }

    log("\n== Creating MPT issuance ==");
    const { issuanceId } = await issuer.createIssuance({
      assetScale: ASSET_SCALE,
      maximumAmount: toBaseUnits("1000000000", ASSET_SCALE),
      transferFee: 0,
      metadata: JSON.stringify({ name: "Regulated Demo Stablecoin", ticker: "RUSD" }),
      allowHolderToHolderTransfer: true,
    });
    log(`  Issuance ID: ${issuanceId}`);

    const issuanceState = await issuer.getIssuance(issuanceId);
    log(
      `  Flags -> requireAuth=${issuanceState.requireAuth} canLock=${issuanceState.canLock} canClawback=${issuanceState.canClawback}`,
    );
    if (!issuanceState.requireAuth || !issuanceState.canLock || !issuanceState.canClawback) {
      throw new Error("Issuance is missing a required compliance flag");
    }

    log("\n== Allowlist: sending before opt-in must fail ==");
    await expectFailure("Payment to A before opt-in", () =>
      issuer.sendTokens(issuanceId, walletA.address, "1"),
    );

    log("\n== Holders opt in (MPTokenAuthorize) ==");
    for (const wallet of [walletA, walletB, walletC]) {
      await holderOptIn(client, wallet, issuanceId);
      log(`  ${wallet.address} opted in`);
    }

    log("\n== Allowlist: sending before issuer approval must still fail ==");
    await expectFailure("Payment to C before issuer approval", () =>
      issuer.sendTokens(issuanceId, walletC.address, "1"),
    );

    log("\n== Allowlist: issuer approves A, B, C ==");
    for (const [label, wallet] of [
      ["A", walletA],
      ["B", walletB],
      ["C", walletC],
    ] as const) {
      await issuer.approveHolder(issuanceId, wallet.address);
      const state = await issuer.getHolder(issuanceId, wallet.address);
      log(`  Holder ${label} approved, authorized=${state?.authorized}`);
    }

    log("\n== Distributing tokens ==");
    await issuer.sendTokens(issuanceId, walletA.address, "500");
    log("  Sent 500 to A");
    await issuer.sendTokens(issuanceId, walletB.address, "1000");
    log("  Sent 1000 to B");
    await issuer.sendTokens(issuanceId, walletC.address, "200");
    log("  Sent 200 to C");

    log("\n== Per-holder freeze: freezing A ==");
    await issuer.freezeHolder(issuanceId, walletA.address);
    // A locked holder can still redeem back to the issuer (mirrors
    // trustline-freeze semantics), so the meaningful check is that they
    // cannot move funds to another holder.
    await expectFailure("A sending to another holder while frozen", () =>
      holderPayment(client, walletA, walletB.address, issuanceId, "1"),
    );
    await expectFailure("A receiving from another holder while frozen", () =>
      holderPayment(client, walletB, walletA.address, issuanceId, "1"),
    );
    log("  Unfreezing A");
    await issuer.unfreezeHolder(issuanceId, walletA.address);
    const aState = await issuer.getHolder(issuanceId, walletA.address);
    log(`  A locked=${aState?.locked} balance=${aState?.balance}`);

    log("\n== Global freeze: locking the entire issuance (while A, B, C are all active) ==");
    await issuer.globalFreeze(issuanceId);
    // Like the per-holder lock, the issuer remains an exempt counterparty
    // under global lock (so clawback and administrative payments keep
    // working during an incident) — the meaningful check is that transfers
    // between two ordinary holders are blocked.
    await expectFailure("A paying B during global freeze", () =>
      holderPayment(client, walletA, walletB.address, issuanceId, "1"),
    );
    log("  Unfreezing globally");
    await issuer.globalUnfreeze(issuanceId);
    const globalFreezeState = await issuer.getIssuance(issuanceId);
    log(`  globallyLocked=${globalFreezeState.globallyLocked}`);

    log("\n== Clawback: clawing back 300 from B ==");
    await issuer.clawback(issuanceId, walletB.address, "300");
    const bAfterClawback = await issuer.getHolder(issuanceId, walletB.address);
    log(`  B balance is now ${bAfterClawback?.balance}`);

    log("\n== Per-holder freeze: freezing B (left frozen) ==");
    await issuer.freezeHolder(issuanceId, walletB.address);
    const bState = await issuer.getHolder(issuanceId, walletB.address);
    log(`  B locked=${bState?.locked}`);

    log("\n== Ban: banning C ==");
    await issuer.banHolder(issuanceId, walletC.address);
    const cState = await issuer.getHolder(issuanceId, walletC.address);
    log(`  C balance=${cState?.balance} authorized=${cState?.authorized}`);
    await expectFailure("Payment to banned C", () =>
      issuer.sendTokens(issuanceId, walletC.address, "1"),
    );

    const finalIssuanceState = await issuer.getIssuance(issuanceId);

    log("\n== Final state ==");
    const finalA = await issuer.getHolder(issuanceId, walletA.address);
    const finalB = await issuer.getHolder(issuanceId, walletB.address);
    const finalC = await issuer.getHolder(issuanceId, walletC.address);
    log(`  A: balance=${finalA?.balance} locked=${finalA?.locked} authorized=${finalA?.authorized}`);
    log(`  B: balance=${finalB?.balance} locked=${finalB?.locked} authorized=${finalB?.authorized}`);
    log(`  C: balance=${finalC?.balance} locked=${finalC?.locked} authorized=${finalC?.authorized}`);

    if (finalA?.balance !== "500" || finalA.locked !== false) {
      throw new Error("Holder A final state does not match expectations");
    }
    if (finalB?.balance !== "700" || finalB.locked !== true) {
      throw new Error("Holder B final state does not match expectations");
    }
    if (finalC?.balance !== "0" || finalC.authorized !== false) {
      throw new Error("Holder C final state does not match expectations");
    }
    if (finalIssuanceState.globallyLocked !== false) {
      throw new Error("Issuance should not be globally locked at the end of the demo");
    }

    const result = {
      issuanceId,
      holders: {
        A: walletA.address,
        B: walletB.address,
        C: walletC.address,
      },
    };
    const resultPath = path.join(process.cwd(), "result.json");
    fs.writeFileSync(resultPath, JSON.stringify(result, null, 2) + "\n");
    log(`\nWrote ${resultPath}`);
  } finally {
    await client.disconnect();
  }
}

main().catch((error) => {
  console.error(error);
  process.exitCode = 1;
});

